create table if not exists public.room_moderators (room_id uuid not null references public.rooms(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), primary key(room_id,user_id));
create table if not exists public.room_bans (room_id uuid not null references public.rooms(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, banned_by uuid not null references public.profiles(id), expires_at timestamptz, created_at timestamptz not null default now(), primary key(room_id,user_id));
create table if not exists public.room_mutes (room_id uuid not null references public.rooms(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, muted_by uuid not null references public.profiles(id), expires_at timestamptz, created_at timestamptz not null default now(), primary key(room_id,user_id));
create table if not exists public.room_seat_invites (id uuid primary key default gen_random_uuid(), room_id uuid not null references public.rooms(id) on delete cascade, inviter_id uuid not null references public.profiles(id), invitee_id uuid not null references public.profiles(id), status text not null default 'pending', created_at timestamptz not null default now());
alter table public.room_moderators enable row level security; alter table public.room_bans enable row level security; alter table public.room_mutes enable row level security; alter table public.room_seat_invites enable row level security;
drop policy if exists room_moderators_read on public.room_moderators; create policy room_moderators_read on public.room_moderators for select using (true);
drop policy if exists room_moderators_owner on public.room_moderators; create policy room_moderators_owner on public.room_moderators for all using (created_by = auth.uid()) with check (created_by = auth.uid());
drop policy if exists room_bans_read on public.room_bans; create policy room_bans_read on public.room_bans for select using (true);
drop policy if exists room_bans_manage on public.room_bans; create policy room_bans_manage on public.room_bans for all using (banned_by = auth.uid()) with check (banned_by = auth.uid());
drop policy if exists room_mutes_read on public.room_mutes; create policy room_mutes_read on public.room_mutes for select using (true);
drop policy if exists room_mutes_manage on public.room_mutes; create policy room_mutes_manage on public.room_mutes for all using (muted_by = auth.uid()) with check (muted_by = auth.uid());
drop policy if exists room_invites_read on public.room_seat_invites; create policy room_invites_read on public.room_seat_invites for select using (invitee_id = auth.uid() or inviter_id = auth.uid());
drop policy if exists room_invites_send on public.room_seat_invites; create policy room_invites_send on public.room_seat_invites for insert with check (inviter_id = auth.uid());
